var CERTCAL_CONTEUDO_MODULO="<style>\n#tplCertCalContainer {\n  color-scheme: light;\n  --bg: var(--bc-bg);\n  --card: var(--bc-surface);\n  --panel: var(--bc-surface);\n  --input: #FFFFFF;\n  --input-hover: var(--bc-surface-2);\n  --text: var(--bc-text);\n  --text-strong: var(--bc-text);\n  --muted: var(--bc-text-3);\n  --muted-2: var(--bc-text-3);\n  --border: var(--bc-line);\n  --border-strong: var(--bc-line-2);\n  --accent: var(--bc-action);\n  --accent-2: var(--bc-action);\n  --success-bg: var(--bc-action-bg);\n  --info-bg: var(--bc-info-bg);\n  --warning-bg: var(--bc-warn-bg);\n  --danger-bg: var(--bc-danger-bg);\n  --shadow-soft: none;\n  --radius: 6px;\n  --radius-sm: 4px;\n}\n#tplCertCalContainer * { box-sizing: border-box; }\n#tplCertCalContainer .hidden { display: none !important; }\n#tplCertCalContainer, #tplCertCalContainer body {\n  font-family: var(--bc-sans);\n  background: transparent !important;\n  color: var(--text) !important;\n}\n#tplCertCalContainer .wrap { max-width: 1100px; margin: 0 auto; padding: 18px; }\n#tplCertCalContainer .header-card {\n  background: #FFFFFF !important; border: 1px solid var(--border); border-radius: var(--radius);\n  padding: 14px 18px; box-shadow: var(--shadow-soft); margin-bottom: 14px;\n  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 14px;\n}\n#tplCertCalContainer .title-area h1 { margin: 0; font-size: 19px; color: var(--text-strong); font-weight: 800; }\n#tplCertCalContainer .title-area p { margin: 5px 0 0; color: var(--muted); font-size: 13px; }\n#tplCertCalContainer .panel {\n  background: #FFFFFF !important; border-radius: var(--radius); padding: 18px;\n  box-shadow: var(--shadow-soft); border: 1px solid var(--border); margin-bottom: 14px;\n}\n#tplCertCalContainer .panel h2 {\n  margin: 0 0 14px; font-size: 14px; color: var(--text-strong) !important;\n  border-bottom: 1px solid var(--border); padding-bottom: 10px; text-transform: none;\n}\n#tplCertCalContainer label { display: block; font-size: 12px; color: var(--muted); margin: 10px 0 4px; }\n#tplCertCalContainer input[type=\"text\"], #tplCertCalContainer input:not([type]), #tplCertCalContainer input[type=\"number\"],\n#tplCertCalContainer input[type=\"file\"], #tplCertCalContainer select, #tplCertCalContainer textarea {\n  width: 100%; background: var(--input) !important; color: var(--text) !important; border: 1px solid var(--border);\n  border-radius: var(--radius-sm); padding: 9px 10px; font-size: 13px;\n}\n#tplCertCalContainer textarea { min-height: 60px; resize: vertical; }\n#tplCertCalContainer .form-row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }\n#tplCertCalContainer .form-row > * { flex: 1; min-width: 180px; }\n#tplCertCalContainer .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n#tplCertCalContainer .grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }\n#tplCertCalContainer .btn, #tplCertCalContainer .btn-primary {\n  border: 1px solid var(--border-strong); background: var(--input); color: var(--text);\n  border-radius: var(--radius-sm); padding: 9px 16px; font-weight: 700; font-size: 13px; cursor: pointer; margin-top: 10px;\n}\n#tplCertCalContainer .btn:hover { background: var(--input-hover); }\n#tplCertCalContainer .btn-primary { background: var(--accent); color: #FFFFFF; border-color: var(--accent); }\n#tplCertCalContainer .btn-primary:hover { filter: brightness(1.08); }\n#tplCertCalContainer .btn-danger { background: var(--danger-bg); color: var(--bc-danger); border-color: var(--bc-danger-line); }\n#tplCertCalContainer .btn-sm { padding: 5px 10px; font-size: 11.5px; margin-top: 0; }\n#tplCertCalContainer .alert-box { border-radius: var(--radius-sm); padding: 10px 12px; font-size: 12.5px; margin-top: 10px; }\n#tplCertCalContainer .alert-box.success { background: var(--success-bg); color: var(--bc-text-2); border: 1px solid var(--bc-action-line); }\n#tplCertCalContainer .alert-box.error { background: var(--danger-bg); color: var(--bc-danger); border: 1px solid var(--bc-danger-line); }\n#tplCertCalContainer .alert-box.info { background: var(--info-bg); color: var(--bc-info); border: 1px solid var(--bc-info-line); }\n#tplCertCalContainer .bloco-card, #tplCertCalContainer .padrao-card {\n  border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px; margin-bottom: 12px; background: #FFFFFF;\n}\n#tplCertCalContainer .bloco-card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }\n#tplCertCalContainer .checkbox-row { display: flex; align-items: center; gap: 8px; margin: 6px 0; }\n#tplCertCalContainer .checkbox-row label { margin: 0; color: var(--text); font-size: 13px; }\n#tplCertCalContainer table.pontos-table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 12px; }\n#tplCertCalContainer table.pontos-table th, #tplCertCalContainer table.pontos-table td { border: 1px solid var(--border); padding: 5px 6px; text-align: center; }\n#tplCertCalContainer table.pontos-table th { background: #FFFFFF; color: var(--muted); font-weight: 700; }\n#tplCertCalContainer table.pontos-table input { text-align: center; padding: 5px 4px; }\n#tplCertCalContainer table.resultado-table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 11.5px; }\n#tplCertCalContainer table.resultado-table th, #tplCertCalContainer table.resultado-table td { border: 1px solid var(--border); padding: 5px 7px; text-align: center; }\n#tplCertCalContainer table.resultado-table th { background: var(--info-bg); color: var(--text-strong); }\n#tplCertCalContainer .cliente-card, #tplCertCalContainer .equip-card { background: var(--success-bg); border: 1px solid var(--bc-action-line); border-radius: var(--radius-sm); padding: 10px 12px; margin-top: 10px; font-size: 13px; }\n#tplCertCalContainer .foto-thumb { display: inline-flex; flex-direction: column; gap: 4px; width: 140px; margin: 6px 8px 6px 0; vertical-align: top; }\n#tplCertCalContainer .foto-thumb img { width: 100%; height: 100px; object-fit: cover; border-radius: 4px; border: 1px solid var(--border); }\n#tplCertCalContainer .foto-thumb input { font-size: 11px; padding: 5px 6px; }\n#tplCertCalContainer .cert-item-row { display: flex; justify-content: space-between; align-items: center; padding: 8px 0; border-bottom: 1px solid var(--border); font-size: 12.5px; gap: 8px; flex-wrap: wrap; }\n#tplCertCalContainer .cert-item-row:last-child { border-bottom: none; }\n#tplCertCalContainer .muted { color: var(--muted); font-size: 12px; }\n\n/* Mobile (2026-08-20): módulo passou a ficar acessível pela grade inicial\n   do celular — sem isto os grid-2/grid-3 ficavam ilegíveis em tela\n   estreita (colunas espremidas) e as tabelas de pontos/resultado\n   estouravam a largura da tela. */\n@media (max-width: 640px) {\n  #tplCertCalContainer .wrap { padding: 10px; }\n  #tplCertCalContainer .grid-2, #tplCertCalContainer .grid-3 { grid-template-columns: 1fr; }\n  #tplCertCalContainer .header-card { flex-direction: column; align-items: flex-start; }\n  #tplCertCalContainer table.pontos-table, #tplCertCalContainer table.resultado-table {\n    display: block; overflow-x: auto; white-space: nowrap;\n  }\n  #tplCertCalContainer .foto-thumb { width: 100%; }\n  #tplCertCalContainer .toc ol { columns: 1; }\n}\n\n/* Manual do Operador — mesmo padrão visual dos outros módulos do Portal\n   (RelCal/CadeiaFrio/Estufa/DeclaracaoExec/PlanCME): .manual-wrap/.toc/\n   .callout escopados ao container, valores rgba() explícitos calculados\n   a partir do --accent real (este projeto usa Comfort Dark sem as\n   variáveis --accent-soft/--accent-border/--panel-soft). */\n#tplCertCalContainer .manual-wrap { max-width: 900px; margin: 0 auto; padding: 18px 18px 60px; line-height: 1.6; }\n#tplCertCalContainer .manual-wrap h1 { font-size: 26px; margin-bottom: 4px; }\n#tplCertCalContainer .manual-wrap .subtitulo { color: var(--muted); margin-top: 0; margin-bottom: 22px; }\n#tplCertCalContainer .manual-wrap h2 { font-size: 19px; margin-top: 40px; padding-bottom: 8px; border-bottom: 1px solid var(--border); color: var(--text-strong); }\n#tplCertCalContainer .manual-wrap h3 { font-size: 15px; margin-top: 26px; color: var(--accent-2); }\n#tplCertCalContainer .manual-wrap p { color: var(--text); }\n#tplCertCalContainer .manual-wrap table { width: 100%; border-collapse: collapse; margin: 14px 0 22px; font-size: 13.5px; }\n#tplCertCalContainer .manual-wrap th, #tplCertCalContainer .manual-wrap td { border: 1px solid var(--border); padding: 8px 10px; text-align: left; vertical-align: top; }\n#tplCertCalContainer .manual-wrap th { background: #FFFFFF; color: var(--text-strong); }\n#tplCertCalContainer .manual-wrap tr:nth-child(even) td { background: var(--bc-surface-2); }\n#tplCertCalContainer .callout { background: var(--bc-action-bg); border: 1px solid var(--bc-action-line); border-left: 4px solid var(--accent); border-radius: var(--radius-sm); padding: 12px 14px; margin: 14px 0; font-size: 13.5px; }\n#tplCertCalContainer .callout strong { color: var(--text-strong); }\n#tplCertCalContainer .manual-wrap ol, #tplCertCalContainer .manual-wrap ul { padding-left: 22px; }\n#tplCertCalContainer .manual-wrap ol li, #tplCertCalContainer .manual-wrap ul li { margin-bottom: 6px; }\n#tplCertCalContainer .toc { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px; margin-bottom: 30px; }\n#tplCertCalContainer .toc h2 { margin-top: 0; border-bottom: none; font-size: 15px; }\n#tplCertCalContainer .toc ol { columns: 2; column-gap: 30px; }\n#tplCertCalContainer .toc a { text-decoration: none; color: var(--accent-2); cursor: pointer; }\n#tplCertCalContainer .toc a:hover { text-decoration: underline; }\n#tplCertCalContainer .topo-link { display: inline-block; margin-top: 30px; }\n</style>\n<script>\nvar certcalState = {\n  cliente: null,\n  unidadeSelecionadaId: null,\n  equipamentos: [],\n  equipamentoSelecionado: null,\n  tecnicos: [],\n  padroes: [],\n  padroesTodos: [],\n  blocos: [],\n  fotos: [],\n  ultimoCertificadoId: null\n};\n\n// Veff: mesma regra de CertCalCalculo.formatarVeff (servidor).\n// 0 (zero = infinito no motor e no cadastro do padrão), infinito ou >= 10.000 -> \"∞\";\n// senão pt-BR com 2 casas. Nunca notação científica.\nfunction tplCertCal_fmtVeff_(v) {\n  if (v === null || v === undefined || typeof v === 'boolean') return '—';\n  var n;\n  if (typeof v === 'number') n = v;\n  else if (typeof v === 'string') {\n    var s = v.trim();\n    if (!s) return '—';\n    if (/^(∞|\\+?inf(init[oy])?)$/i.test(s)) return '∞';\n    if (s.indexOf(',') !== -1) s = s.replace(/\\./g, '').replace(',', '.');\n    if (!/^[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:e[+-]?\\d+)?$/i.test(s)) return s;\n    n = Number(s);\n  } else return '—';\n  if (isNaN(n) || n < 0) return '—';\n  if (n === 0 || !isFinite(n) || n >= 10000) return '∞';\n  var partes = n.toFixed(2).split('.');\n  return partes[0].replace(/\\B(?=(\\d{3})+(?!\\d))/g, '.') + ',' + partes[1];\n}\n\nfunction tplCertCal_familiaGrandeza_(texto) {\n  var t = String(texto || '').toLowerCase();\n  if (t.indexOf('%') !== -1 || t.indexOf('umid') !== -1 || t.indexOf('higrometr') !== -1) return 'umidade';\n  if (t.indexOf('°c') !== -1 || t.indexOf('ºc') !== -1 || t.indexOf('temperatura') !== -1 || t.indexOf('celsius') !== -1 || t.indexOf('termo') !== -1 || t.indexOf('grau') !== -1) return 'temperatura';\n  if (/rpm|rotação|rotacao|centríf|centrif|tac[oô]met/.test(t)) return 'rotacao';\n  if (t.indexOf('kpa') !== -1 || t.indexOf('mpa') !== -1 || t.indexOf('bar') !== -1 || t.indexOf('mmhg') !== -1 || t.indexOf('pressao') !== -1 || t.indexOf('pressão') !== -1 || t.indexOf('psi') !== -1) return 'pressao';\n  return null;\n}\n\nfunction tplCertCal_avisoPadraoDivergente_(bloco) {\n  var familiaBloco = tplCertCal_familiaGrandeza_(bloco.unidade) || tplCertCal_familiaGrandeza_(bloco.titulo);\n  if (!familiaBloco) return '';\n  var divergentes = (bloco.padroesIds || []).map(function(id) {\n    return certcalState.padroes.filter(function(p) { return p.ID === id; })[0];\n  }).filter(function(p) {\n    if (!p) return false;\n    var familiaPadrao = tplCertCal_familiaGrandeza_(p.DESCRICAO) || tplCertCal_familiaGrandeza_(p.TAG);\n    return familiaPadrao && familiaPadrao !== familiaBloco;\n  });\n  if (!divergentes.length) return '';\n  var nomes = divergentes.map(function(p) { return p.TAG; }).join(', ');\n  return '<div class=\"alert-box error\">O padrão ' + nomes + ' parece ser de outra grandeza (bloco declarado como \"' + bloco.unidade + '\"). Confira se marcou o padrão certo antes de gerar.</div>';\n}\n\nfunction tplCertCal_atualizarAvisoPadrao_(blocoIdx) {\n  var el = document.getElementById('certcal-aviso-' + blocoIdx);\n  if (!el) return;\n  el.innerHTML = tplCertCal_avisoPadraoDivergente_(certcalState.blocos[blocoIdx]);\n}\n\nvar CERTCAL_API_EM_VOO = {};\nfunction tplCertCal_chamarApi(fn, payload) {\n  var altera = /Criar|Atualizar|Anexar|Inativar|Reativar|Gerar/.test(fn);\n  if (altera && CERTCAL_API_EM_VOO[fn]) return Promise.reject(new Error('Esta ação já está sendo processada. Aguarde a conclusão.'));\n  if (altera) CERTCAL_API_EM_VOO[fn] = true;\n  return new Promise(function(resolve, reject) {\n    if (typeof SGO_iniciarCarregamento_ === 'function') SGO_iniciarCarregamento_(altera ? 'Aguarde, gerando ou salvando...' : 'Aguarde, carregando informações...');\n    google.script.run\n      .withSuccessHandler(function(res) { if(altera) delete CERTCAL_API_EM_VOO[fn]; if (typeof SGO_finalizarCarregamento_ === 'function') SGO_finalizarCarregamento_(); resolve(res); })\n      .withFailureHandler(function(err) { if(altera) delete CERTCAL_API_EM_VOO[fn]; if (typeof SGO_finalizarCarregamento_ === 'function') SGO_finalizarCarregamento_(); reject(err); })\n      .CertCal_apiDispatch({ sessionId: SGO_getSessionId(), fn: fn, payload: payload || {} });\n  });\n}\n\nfunction tplCertCal_msg(containerId, tipo, texto) {\n  var el = document.getElementById(containerId);\n  if (!el) return;\n  el.innerHTML = '<div class=\"alert-box ' + tipo + '\">' + texto + '</div>';\n}\n\nfunction tplCertCal_erro(containerId, err) {\n  var msg = (err && err.message) ? err.message : String(err);\n  tplCertCal_msg(containerId, 'error', msg);\n}\n\nfunction tplCertCal_renderReal_() {\n  var container = document.getElementById('tplCertCalContainer');\n  if (!container) return;\n\n  container.innerHTML =\n    '<div id=\"tplCertCal_viewModulo\">' +\n    '<div class=\"wrap\">' +\n\n    '  <div class=\"panel\" id=\"certcal-panel-relatorios-gestao\">' +\n    '    <h2>Relatórios gerenciais dos padrões</h2>' +\n    '    <p class=\"muted\">Gere um plano completo de renovação e auditoria dos padrões ou acompanhe o desempenho do módulo. Os relatórios abrem prontos para imprimir ou salvar em PDF A4.</p>' +\n    '    <div class=\"form-row\">' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_gerarRelatorioGestao_(\\'RENOVACAO\\')\">Plano de renovação e auditoria</button>' +\n    '      <select id=\"certcal-gestao-periodo\"><option value=\"30\">Últimos 30 dias</option><option value=\"90\" selected>Últimos 90 dias</option><option value=\"365\">Últimos 12 meses</option><option value=\"0\">Todo o histórico</option></select>' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_gerarRelatorioGestao_(\\'DESEMPENHO\\')\">Relatório de desempenho</button>' +\n    '    </div>' +\n    '    <div id=\"certcal-gestao-relatorios-status\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\" id=\"certcal-panel-padroes\">' +\n    '    <h2>Cadastro e validade dos padrões</h2>' +\n    '    <p class=\"muted\">Cadastre e acompanhe a validade dos padrões. Um mesmo certificado pode ter vários cadastros: use uma TAG e descrição para cada grandeza ou canal, com seus próprios valores de U95 e K. Nos números, vírgula e ponto são aceitos como separador decimal.</p>' +\n    '    <div id=\"certcal-padroes-alerta\"></div>' +\n    '    <div id=\"certcal-padroes-tabela\" class=\"muted\">Carregando padrões...</div>' +\n    '    <button class=\"btn\" onclick=\"tplCertCal_abrirNovoPadrao()\">+ Cadastrar novo padrão</button>' +\n    '    <div id=\"certcal-padrao-novo\" class=\"hidden padrao-card\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Identificação (TAG)</label><input id=\"certcal-padrao-tag\" placeholder=\"Ex.: THM-002\"></div>' +\n    '        <div><label>Descrição</label><input id=\"certcal-padrao-descricao\" placeholder=\"Ex.: Registro de temperatura e umidade\"></div>' +\n    '        <div><label>Nº do certificado do padrão</label><input id=\"certcal-padrao-certificado\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Incerteza (U95)</label><input id=\"certcal-padrao-u95\"></div>' +\n    '        <div><label>Fator K (padrão 2)</label><input id=\"certcal-padrao-k\" value=\"2\"></div>' +\n    '        <div><label>Graus de liberdade (0 = infinito)</label><input id=\"certcal-padrao-veff\" value=\"0\"></div>' +\n    '      </div>' +\n    '      <label>Validade</label><input id=\"certcal-padrao-validade\" placeholder=\"dd/mm/aaaa\">' +\n    '      <label>Certificado do padrão (PDF, opcional)</label>' +\n    '      <input type=\"file\" id=\"certcal-padrao-certificado-arquivo\" accept=\"application/pdf\" data-rotulo=\"Escolher PDF\">' +\n    '      <button class=\"btn-primary\" onclick=\"tplCertCal_criarPadrao()\">Salvar padrão</button>' +\n    '      <div id=\"certcal-padrao-status\"></div>' +\n    '    </div>' +\n    '    <div id=\"certcal-padrao-editar\" class=\"hidden padrao-card\">' +\n    '      <input type=\"hidden\" id=\"certcal-padrao-edit-id\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Identificação (TAG)</label><input id=\"certcal-padrao-edit-tag\"></div>' +\n    '        <div><label>Descrição</label><input id=\"certcal-padrao-edit-descricao\"></div>' +\n    '        <div><label>Nº do certificado do padrão</label><input id=\"certcal-padrao-edit-certificado\"></div>' +\n    '      </div>' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Incerteza (U95)</label><input id=\"certcal-padrao-edit-u95\"></div>' +\n    '        <div><label>Fator K (padrão 2)</label><input id=\"certcal-padrao-edit-k\"></div>' +\n    '        <div><label>Graus de liberdade (0 = infinito)</label><input id=\"certcal-padrao-edit-veff\"></div>' +\n    '      </div>' +\n    '      <label>Validade</label><input id=\"certcal-padrao-edit-validade\" placeholder=\"dd/mm/aaaa\">' +\n    '      <label>Substituir certificado do padrão (PDF, opcional)</label>' +\n    '      <input type=\"file\" id=\"certcal-padrao-edit-certificado-arquivo\" accept=\"application/pdf\" data-rotulo=\"Escolher PDF\">' +\n    '      <button class=\"btn-primary\" onclick=\"tplCertCal_salvarEdicaoPadrao()\">Salvar alterações</button>' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_cancelarEdicaoPadrao()\">Cancelar</button>' +\n    '      <div id=\"certcal-padrao-edit-status\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel\">' +\n    '    <h2>1. Cliente</h2>' +\n    '    <div class=\"form-row\">' +\n    '      <input id=\"certcal-cnpj\" placeholder=\"CNPJ do cliente (só números)\">' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_buscarCliente()\">Buscar / Selecionar Cliente</button>' +\n    '    </div>' +\n    '    <div id=\"certcal-cliente-status\"></div>' +\n    '    <div id=\"certcal-cliente-novo\" class=\"hidden\">' +\n    '      <div class=\"grid-2\">' +\n    '        <div><label>Razão social</label><input id=\"certcal-novo-razaoSocial\"></div>' +\n    '        <div><label>Nome fantasia</label><input id=\"certcal-novo-nomeFantasia\"></div>' +\n    '      </div>' +\n    '      <label>Endereço</label><input id=\"certcal-novo-endereco\">' +\n    '      <div class=\"grid-3\">' +\n    '        <div><label>Contato</label><input id=\"certcal-novo-contato\"></div>' +\n    '        <div><label>E-mail</label><input id=\"certcal-novo-email\"></div>' +\n    '        <div><label>Telefone</label><input id=\"certcal-novo-telefone\"></div>' +\n    '      </div>' +\n    '      <button class=\"btn-primary\" onclick=\"tplCertCal_criarCliente()\">Cadastrar Cliente</button>' +\n    '    </div>' +\n    '    <div id=\"certcal-cliente-selecionado\" class=\"hidden cliente-card\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel hidden\" id=\"certcal-panel-equipamento\">' +\n    '    <h2>2. Equipamento</h2>' +\n    '    <label>Equipamento já cadastrado</label>' +\n    '    <div class=\"form-row\">' +\n    '      <select id=\"certcal-equipamento-existente\"><option value=\"\">— selecione —</option></select>' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_selecionarEquipamentoExistente()\">Usar este equipamento</button>' +\n    '    </div>' +\n    '    <p class=\"muted\">ou cadastre um novo equipamento:</p>' +\n    '    <label>Unidade</label>' +\n    '    <select id=\"certcal-unidade\"></select>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Descrição/Tipo (ex.: Termo higrômetro)</label><input id=\"certcal-eq-tipo\"></div>' +\n    '      <div><label>Fabricante</label><input id=\"certcal-eq-fabricante\"></div>' +\n    '      <div><label>Modelo</label><input id=\"certcal-eq-modelo\"></div>' +\n    '    </div>' +\n    '    <div class=\"grid-3\">' +\n    '      <div><label>Nº de série</label><input id=\"certcal-eq-serie\"></div>' +\n    '      <div><label>TAG</label><input id=\"certcal-eq-tag\"></div>' +\n    '      <div><label>Setor</label><input id=\"certcal-eq-setor\"></div>' +\n    '    </div>' +\n    '    <button class=\"btn-primary\" onclick=\"tplCertCal_criarEquipamento()\">Cadastrar Equipamento</button>' +\n    '    <div id=\"certcal-equipamento-status\"></div>' +\n    '    <div id=\"certcal-equipamento-selecionado\" class=\"hidden equip-card\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel hidden\" id=\"certcal-panel-calibracao\">' +\n    '    <h2>3. Dados da calibração</h2>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Técnico executor (cadastrado)</label>' +\n    '        <div class=\"form-row\"><select id=\"certcal-tecnico\"><option value=\"\">— nenhum —</option></select>' +\n    '        <button class=\"btn btn-sm\" onclick=\"tplCertCal_abrirNovoTecnico()\">+ Novo</button></div>' +\n    '        <div id=\"certcal-tecnico-novo\" class=\"hidden\" style=\"margin-top:8px;\">' +\n    '          <input id=\"certcal-tecnico-novo-nome\" placeholder=\"Nome do técnico\">' +\n    '          <button class=\"btn btn-sm btn-primary\" style=\"margin-top:6px;\" onclick=\"tplCertCal_criarTecnico()\">Salvar técnico</button>' +\n    '          <div id=\"certcal-tecnico-status\"></div>' +\n    '        </div>' +\n    '      </div>' +\n    '      <div><label>ou nome do técnico executor (texto livre)</label><input id=\"certcal-tecnico-livre\"></div>' +\n    '    </div>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Data da calibração (dd/mm/aaaa)</label><input id=\"certcal-data-calibracao\"></div>' +\n    '    </div>' +\n    \"<label>O cliente solicitou a inclusão da data de próxima calibração?</label>\" +\n    \"<div class=\\\"checkbox-row\\\"><input type=\\\"radio\\\" name=\\\"certcal-proxima-solicitada\\\" id=\\\"certcal-proxima-nao\\\" value=\\\"NAO\\\" checked onchange=\\\"tplCertCal_alternarProximaCalibracao_()\\\"><label for=\\\"certcal-proxima-nao\\\">Não — emissão sem data (seleção padrão).</label></div>\" +\n    \"<div class=\\\"checkbox-row\\\"><input type=\\\"radio\\\" name=\\\"certcal-proxima-solicitada\\\" id=\\\"certcal-proxima-sim\\\" value=\\\"SIM\\\" onchange=\\\"tplCertCal_alternarProximaCalibracao_()\\\"><label for=\\\"certcal-proxima-sim\\\">Sim — incluir data informada pelo cliente.</label></div>\" +\n    \"<div id=\\\"certcal-proxima-campos\\\" class=\\\"hidden\\\">\" +\n    \"<label>Data solicitada de próxima calibração (dd/mm/aaaa)</label><input id=\\\"certcal-proxima-data\\\" placeholder=\\\"dd/mm/aaaa\\\" disabled>\" +\n    \"<label>Nome do solicitante</label><input id=\\\"certcal-proxima-solicitante\\\" disabled>\" +\n    \"<label>Cargo/setor do solicitante</label><input id=\\\"certcal-proxima-cargo-setor\\\" disabled>\" +\n    \"<label>Referência da solicitação (OS, email, contrato ou documento)</label><input id=\\\"certcal-proxima-referencia\\\" disabled>\" +\n    \"<label>Observação (opcional)</label><textarea id=\\\"certcal-proxima-observacao\\\" disabled></textarea>\" +\n    \"</div>\" +\n    \"<p class=\\\"muted\\\">A data é informada por solicitação do cliente. O laboratório não define automaticamente intervalo, validade ou adequação ao uso.</p>\" +\n    '    <div class=\"checkbox-row\"><input type=\"checkbox\" id=\"certcal-local-lab\" checked><label for=\"certcal-local-lab\">Realizado no laboratório da Metrolabs</label></div>' +\n    '    <label>Condições ambientais (opcional — só os números; o texto é fixo)</label>' +\n    '    <div class=\"grid-2\">' +\n    '      <div><label>Temperatura ambiente (°C)</label><input id=\"certcal-temp-ambiente\" placeholder=\"Ex.: 23,5\"></div>' +\n    '      <div><label>Umidade Relativa do ar (%)</label><input id=\"certcal-umidade-ambiente\" placeholder=\"Ex.: 62,0\"></div>' +\n    '    </div>' +\n    '  </div>' +\n\n    '  <div class=\"panel hidden\" id=\"certcal-panel-blocos\">' +\n    '    <h2>4. Ensaios (blocos de resultado)</h2>' +\n    '    <p class=\"muted\">Cada bloco é uma grandeza/canal medido nesta calibração (ex.: \"Sensor Interno — Temperatura\", \"Sensor Externo\", \"Umidade\"). Cada ponto tem um valor de Referência e ' + certcalNumLeiturasTexto_() + ' (Ensaio 1/2/3).</p>' +\n    '    <div id=\"certcal-blocos-lista\"></div>' +\n    '    <button class=\"btn\" onclick=\"tplCertCal_adicionarBloco()\">+ Adicionar bloco de ensaio</button>' +\n    '    <button class=\"btn-primary\" onclick=\"tplCertCal_calcularPreview()\">Calcular</button>' +\n    '    <div id=\"certcal-preview-resultado\"></div>' +\n    '  </div>' +\n\n\n    '  <div class=\"panel hidden\" id=\"certcal-panel-fotos\">' +\n    '    <h2>5. Fotos do ensaio (opcional)</h2>' +\n    '    <input type=\"file\" id=\"certcal-fotos-input\" multiple accept=\"image/*\" data-rotulo=\"Escolher fotos\" onchange=\"tplCertCal_onFotosSelecionadas()\">' +\n    '    <div id=\"certcal-fotos-lista\" style=\"margin-top:10px;\"></div>' +\n    '  </div>' +\n\n    '  <div class=\"panel hidden\" id=\"certcal-panel-gerar\">' +\n    '    <h2>6. Gerar</h2>' +\n    '    <p class=\"muted hidden\" id=\"certcal-panel-responsabilidade\">O laboratório apresenta os resultados da calibração. A avaliação da adequação ao uso e a decisão de aceitação cabem ao setor de qualidade do cliente.</p>' +\n    '    <button class=\"btn-primary\" id=\"certcal-btn-gerar\" onclick=\"tplCertCal_gerarCertificado()\">Gerar Certificado de Calibração</button>' +\n    '    <div id=\"certcal-resultado-certificado\"></div>' +\n    '    <button class=\"btn hidden\" id=\"certcal-btn-interpretativo\" onclick=\"tplCertCal_gerarRelatorioInterpretativo()\">Gerar Relatório Interpretativo</button>' +\n    '    <div id=\"certcal-resultado-interpretativo\"></div>' +\n    '  </div>' +\n    '  <div class=\"panel\" id=\"certcal-panel-emitidos\">' +\n    '    <h2>Certificados emitidos</h2>' +\n    '    <p class=\"muted\">Digite o CNPJ do cliente para reabrir um certificado já emitido e o relatório interpretativo, se houver.</p>' +\n    '    <div class=\"form-row\">' +\n    '      <input id=\"certcal-busca-cnpj\" placeholder=\"CNPJ do cliente\">' +\n    '      <button class=\"btn\" onclick=\"tplCertCal_buscarPorCnpj()\">Buscar</button>' +\n    '    </div>' +\n    '    <div id=\"certcal-busca-resultado\"></div>' +\n    '  </div>' +\n    '</div>' +\n    '</div>' +\n    '<div id=\"tplCertCal_viewManual\" style=\"display:none\">' + tplCertCal_manualHtml_() + '</div>';\n\n  // Cadastros carregados juntos por pdMount/pdLoad, sem consultas simultâneas.\n  if (!certcalState.blocos.length) tplCertCal_adicionarBloco();\n}\n\nfunction tplCertCal_abrirManual_() {\n  var viewModulo = document.getElementById('tplCertCal_viewModulo');\n  var viewManual = document.getElementById('tplCertCal_viewManual');\n  if (viewModulo) viewModulo.style.display = 'none';\n  if (viewManual) viewManual.style.display = '';\n}\n\nfunction tplCertCal_voltarDoManual_() {\n  var viewModulo = document.getElementById('tplCertCal_viewModulo');\n  var viewManual = document.getElementById('tplCertCal_viewManual');\n  if (viewManual) viewManual.style.display = 'none';\n  if (viewModulo) viewModulo.style.display = '';\n}\n\nfunction tplCertCal_irParaSecao_(id) {\n  var el = document.getElementById(id);\n  if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\nfunction tplCertCal_manualHtml_() {\n  return `\n<div class=\"wrap manual-wrap\">\n\n  <header class=\"header-card\" style=\"position:static; margin-bottom:24px;\">\n    <div class=\"title-area\">\n      <h1 style=\"margin-bottom:4px;\">Manual do Operador</h1>\n      <p style=\"margin:0;\">Certificado de Calibração — emissão do certificado oficial + relatório interpretativo</p>\n    </div>\n    <button type=\"button\" class=\"btn\" onclick=\"tplCertCal_voltarDoManual_()\">← Voltar ao sistema</button>\n  </header>\n\n  <div class=\"toc\" id=\"tplCertCal_topoManual\">\n    <h2>Índice</h2>\n    <ol>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms1')\">Como usar este manual</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms2')\">O que este sistema faz</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms3')\">Mapa da tela</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms4')\">Padrões de Referência do Laboratório</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms5')\">Seção 1 — Cliente</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms6')\">Seção 2 — Equipamento</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms7')\">Seção 3 — Dados da calibração</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms8')\">Seção 4 — Ensaios (blocos de resultado)</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms9')\">Seção 5 — Avaliação pelo cliente</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms10')\">Seção 6 — Fotos do ensaio</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms11')\">Seção 7 — Gerar</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms12')\">Consultar certificados por CNPJ</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms13')\">Passo a passo completo</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms14')\">Erros comuns</a></li>\n      <li><a onclick=\"tplCertCal_irParaSecao_('tplCertCal_ms15')\">Glossário</a></li>\n    </ol>\n  </div>\n\n  <h2 id=\"tplCertCal_ms1\">1. Como usar este manual</h2>\n  <p>Este manual foi escrito para quem <strong>nunca usou o sistema e não precisa entender de metrologia</strong> para operá-lo. Cada campo da tela está explicado em quatro partes: <strong>o que é</strong> (o nome em português simples), <strong>para que serve</strong> (por que o campo existe), <strong>o que fazer</strong> (como preencher na prática) e <strong>o que acontece</strong> (o resultado de preencher certo, errado ou deixar em branco).</p>\n  <p>Leia na ordem, de cima para baixo, seguindo a tela também de cima para baixo. Se aparecer uma palavra técnica desconhecida, vá direto ao <strong>Glossário</strong> (seção 15).</p>\n\n  <h2 id=\"tplCertCal_ms2\">2. O que este sistema faz, em uma frase</h2>\n  <p>Você digita as leituras feitas durante a calibração de um equipamento (por comparação com um padrão de referência) e o sistema <strong>calcula sozinho</strong> a tendência, a incerteza e monta o <strong>Certificado de Calibração oficial</strong>, pronto pra imprimir — exatamente no mesmo formato que a Metrolabs já usa.</p>\n  <div class=\"callout\"><strong>Diferença importante:</strong> isto não é o módulo \"Relatório de Calibração\" (que só lê um certificado que já existe, pronto). Aqui não existe certificado prévio — é este sistema que <strong>emite</strong> o certificado do zero, fazendo a conta de verdade.</div>\n  <p>Depois de emitir o certificado, você pode gerar, com 1 clique a mais, um <strong>Relatório Interpretativo</strong> — um segundo documento, em linguagem simples, explicando o que os números do certificado significam.</p>\n\n  <h2 id=\"tplCertCal_ms3\">3. Mapa da tela — visão geral</h2>\n  <ol>\n    <li><strong>1. Cliente</strong> — quem é o dono do equipamento calibrado.</li>\n    <li><strong>2. Equipamento</strong> — qual equipamento foi calibrado.</li>\n    <li><strong>3. Dados da calibração</strong> — técnico, data, local, condições ambientais.</li>\n    <li><strong>4. Ensaios (blocos de resultado)</strong> — onde você digita as leituras e o sistema calcula.</li>\n    <li><strong>5. Fotos do ensaio</strong> — opcional.</li>\n    <li><strong>6. Gerar</strong> — botões finais e a nota sobre a avaliação pelo cliente.</li>\n    <li><strong>Certificados emitidos</strong> — no fim da página, para reabrir um certificado pelo CNPJ.</li>\n  </ol>\n  <p>O cadastro e a validade dos padrões, o inventário, o orçamento e os relatórios gerenciais ficam na página <strong>Padrões de referência</strong> do menu.</p>\n\n  <h2 id=\"tplCertCal_ms4\">4. Padrões de Referência do Laboratório</h2>\n  <p>Um <strong>padrão de referência</strong> é o instrumento que a Metrolabs usa para comparar e calibrar o equipamento do cliente. Todo padrão tem sua própria validade — se ele vencer, qualquer calibração feita com ele fica questionável. O cadastro fica na página <strong>Padrões de referência</strong> do menu.</p>\n  <table>\n    <tr><th>Campo</th><th>O que é</th><th>O que fazer</th></tr>\n    <tr><td>Identificação (TAG)</td><td>Código do padrão (ex.: \"THM-002\")</td><td>Digite o código físico do instrumento-padrão</td></tr>\n    <tr><td>Descrição</td><td>O que é o padrão</td><td>Ex.: \"Registro de temperatura e umidade\"</td></tr>\n    <tr><td>Nº do certificado do padrão</td><td>Número do certificado de calibração do próprio padrão</td><td>Copie do certificado do padrão</td></tr>\n    <tr><td>Incerteza (U95)</td><td>Valor de incerteza expandida do certificado do padrão</td><td>Copie exatamente como está no certificado</td></tr>\n    <tr><td>Fator K (padrão 2)</td><td>Fator de abrangência do certificado do padrão</td><td>Deixe 2, a menos que o certificado diga outro valor</td></tr>\n    <tr><td>Graus de liberdade (0 = infinito)</td><td>Número técnico do cálculo de incerteza do padrão</td><td>Deixe 0 — é o caso normal</td></tr>\n    <tr><td>Validade</td><td>Até quando o padrão pode ser usado</td><td>dd/mm/aaaa</td></tr>\n    <tr><td>Certificado do padrão (PDF)</td><td>Arquivo do certificado do próprio padrão</td><td>Anexe o PDF (opcional, mas recomendado)</td></tr>\n  </table>\n  <h3>Status de validade (selo colorido)</h3>\n  <table>\n    <tr><th>Selo</th><th>O que significa</th></tr>\n    <tr><td>Vigente</td><td>Mais de 30 dias até vencer</td></tr>\n    <tr><td>Vence em até 30 dias</td><td>Vence em 30 dias ou menos</td></tr>\n    <tr><td>Vencido</td><td>Já passou da validade: o certificado não é emitido com ele</td></tr>\n    <tr><td>Sem validade informada</td><td>Nenhuma data foi cadastrada</td></tr>\n  </table>\n  <div class=\"callout\"><strong>O que acontece se algum padrão estiver vencendo ou vencido?</strong> Aparece um aviso vermelho no topo deste bloco. O mesmo aviso aparece no Início do SGO+ e como número vermelho no item Padrões de referência do menu lateral — em qualquer tela, não só aqui. A ideia é você nunca ser pego de surpresa usando um padrão vencido sem perceber.</div>\n  <p>Na tabela de padrões, a coluna \"Certificado (PDF)\" tem o botão \"Anexar PDF\" (ou \"Substituir PDF\") — use para anexar o certificado depois ou trocar por um renovado. Um padrão fora de uso não precisa ser excluído — clique em <strong>Inativar</strong> (ele some da lista de seleção, mas continua no histórico); <strong>Reativar</strong> traz de volta.</p>\n\n  <h2 id=\"tplCertCal_ms5\">5. Seção 1 — Cliente</h2>\n  <table>\n    <tr><th>Campo</th><th>O que é</th><th>O que fazer</th></tr>\n    <tr><td>CNPJ</td><td>Número de identificação da empresa cliente</td><td>Digite (só números) e clique em \"Buscar / Selecionar Cliente\"</td></tr>\n  </table>\n  <div class=\"callout\"><strong>O que acontece?</strong> Se o CNPJ já existe no cadastro, o cliente é selecionado automaticamente. Se não existe, o sistema consulta a Receita Federal e pré-preenche um formulário de cadastro novo — confira os dados e clique em \"Cadastrar Cliente\". O cliente fica cadastrado e pode ser usado em qualquer certificado futuro.</div>\n\n  <h2 id=\"tplCertCal_ms6\">6. Seção 2 — Equipamento</h2>\n  <p>Depois de selecionar o cliente, você escolhe um equipamento já cadastrado, ou cadastra um novo (Unidade, Descrição/Tipo, Fabricante, Modelo, Nº de série, TAG, Setor). Um equipamento novo fica cadastrado — nas próximas calibrações desse cliente, ele já aparece na lista, sem precisar digitar tudo de novo.</p>\n\n  <h2 id=\"tplCertCal_ms7\">7. Seção 3 — Dados da calibração</h2>\n  <table>\n    <tr><th>Campo</th><th>O que fazer</th></tr>\n    <tr><td>Técnico executor (cadastrado)</td><td>Escolha na lista, ou clique em \"+ Novo\" pra cadastrar um técnico (só o nome, sem login)</td></tr>\n    <tr><td>ou nome do técnico executor (texto livre)</td><td>Digite direto, quando o técnico não está cadastrado</td></tr>\n    <tr><td>Data da calibração</td><td>dd/mm/aaaa</td></tr>\n    <tr><td>Data de próxima calibração solicitada pelo cliente</td><td>NÃO por padrão. Se SIM, informe a data solicitada, nome, cargo/setor e referência da solicitação; observação é opcional. O laboratório não calcula intervalo automaticamente.</td></tr>\n    <tr><td>Realizado no laboratório da Metrolabs</td><td>Deixe marcado se foi no laboratório; desmarque se foi no cliente</td></tr>\n    <tr><td>Temperatura ambiente (°C) / Umidade Relativa (%)</td><td>Digite só o número — o texto ao redor é sempre igual pra todo mundo</td></tr>\n  </table>\n\n  <h2 id=\"tplCertCal_ms8\">8. Seção 4 — Ensaios (blocos de resultado)</h2>\n  <p>Esta é a parte principal — onde o cálculo acontece de verdade. Um <strong>bloco</strong> é uma grandeza física medida (ex.: \"Temperatura\", \"Umidade\", ou \"Sensor Interno\"/\"Sensor Externo\" — dois blocos separados). Um certificado pode ter vários blocos.</p>\n  <p>Dentro de cada bloco, um <strong>ponto</strong> é um valor de referência testado. Cada ponto tem uma <strong>Referência</strong> (valor de referência informado conforme o procedimento) e <strong>3 leituras</strong> (Ensaio 1, Ensaio 2, Ensaio 3) — as 3 medições reais feitas no equipamento, naquele ponto.</p>\n  <table>\n    <tr><th>Campo</th><th>O que fazer</th></tr>\n    <tr><td>Título (grandeza/canal)</td><td>Ex.: \"Sensor Interno — Temperatura\"</td></tr>\n    <tr><td>Unidade</td><td>Ex.: \"°C\", \"% UR\"</td></tr>\n    <tr><td>Padrões de referência usados neste bloco</td><td>Marque um ou mais padrões cadastrados</td></tr>\n    <tr><td>Referência (Nominal)</td><td>Informe o valor de referência conforme o procedimento; a identificação de sua origem permanece uma pendência técnica</td></tr>\n    <tr><td>Ensaio 1 / Ensaio 2 / Ensaio 3</td><td>Digite os 3 valores medidos</td></tr>\n  </table>\n  <p>Use \"+ Adicionar ponto\" pra incluir mais pontos no mesmo bloco, e \"+ Adicionar bloco de ensaio\" pra incluir outra grandeza. Depois de preencher, clique em <strong>\"Calcular\"</strong> pra ver uma prévia da tabela de resultados antes de gerar o certificado final.</p>\n  <div class=\"callout\"><strong>O que acontece se eu não marcar nenhum padrão num bloco?</strong> O sistema pede ao menos um padrão por bloco antes de calcular. Selecione o cadastro correspondente à grandeza ensaiada.</div>\n\n  <h2 id=\"tplCertCal_ms9\">9. Avaliação pelo cliente (nota na seção 6)</h2>\n  <p>O laboratório entrega os resultados, a tendência e a incerteza da calibração. O setor de qualidade do cliente define os critérios de aceitação e avalia a adequação ao uso.</p>\n  <div class=\"callout\"><strong>Responsabilidade:</strong> o certificado e o relatório interpretativo não emitem decisão de aceitação do equipamento.</div>\n\n  <h2 id=\"tplCertCal_ms10\">10. Seção 5 — Fotos do ensaio (opcional)</h2>\n  <p>Anexe até 8 fotos tiradas durante a calibração, com legenda opcional. Se você não escrever legenda e depois gerar o Relatório Interpretativo, a Inteligência Artificial escreve uma descrição sozinha.</p>\n\n  <h2 id=\"tplCertCal_ms11\">11. Seção 6 — Gerar</h2>\n  <h3>Gerar Certificado de Calibração</h3>\n  <ol>\n    <li>Clique em \"Gerar Certificado de Calibração\".</li>\n    <li>Uma nova aba abre imediatamente, mostrando \"Gerando certificado, aguarde...\".</li>\n    <li>O sistema recalcula tudo no servidor (nunca confia em conta feita no navegador) e a aba é preenchida com o certificado final, pronto pra imprimir.</li>\n    <li>O certificado é salvo automaticamente no SGO+, na pasta do cliente.</li>\n    <li>O número do certificado é gerado sozinho (ano + sequencial) — você não digita em lugar nenhum.</li>\n  </ol>\n  <h3>Gerar Relatório Interpretativo</h3>\n  <p>Depois do certificado gerado, aparece um segundo botão. Ao clicar, a IA escreve uma explicação didática dos mesmos números (sem recalcular nada), com conclusão técnica e conclusão em linguagem simples — pode levar até 1 minuto. Também é salvo automaticamente na pasta do cliente.</p>\n  <div class=\"callout\">Este relatório é opcional e separado do certificado. O certificado sozinho já é um documento completo e válido.</div>\n\n  <h2 id=\"tplCertCal_ms12\">12. Consultar certificados já emitidos (por CNPJ)</h2>\n  <p>No fim da página, em \"Certificados emitidos\", digite o CNPJ e clique em \"Buscar\" — aparece a lista de certificados desse cliente, com botões \"Reabrir certificado\" e link direto pro Relatório Interpretativo, se já tiver sido gerado.</p>\n\n  <h2 id=\"tplCertCal_ms13\">13. Passo a passo completo</h2>\n  <ol>\n    <li>Confira se algum padrão está vencendo/vencido.</li>\n    <li>Padrões: use os com selo verde; cadastre novos se precisar.</li>\n    <li>Seção 1: CNPJ, buscar/cadastrar cliente.</li>\n    <li>Seção 2: escolher ou cadastrar o equipamento.</li>\n    <li>Seção 3: técnico, data, local, condições ambientais.</li>\n    <li>Seção 4: monte os blocos, marque os padrões, preencha os pontos, clique em \"Calcular\".</li>\n    <li>Seção 5: anexe fotos, se tiver.</li>\n    <li>Seção 6: o setor de qualidade do cliente avalia a adequação ao uso (nota acima do botão).</li>\n    <li>Clique em \"Gerar Certificado de Calibração\".</li>\n    <li>Se quiser, clique em \"Gerar Relatório Interpretativo\".</li>\n  </ol>\n\n  <h2 id=\"tplCertCal_ms14\">14. Erros comuns e o que fazer</h2>\n  <table>\n    <tr><th>O que aconteceu</th><th>O que fazer</th></tr>\n    <tr><td>\"Selecione o cliente e o equipamento antes de gerar\"</td><td>Volte e complete cliente + equipamento</td></tr>\n    <tr><td>\"Adicione ao menos 1 bloco de ensaio\"</td><td>Clique em \"+ Adicionar bloco de ensaio\"</td></tr>\n    <tr><td>Números da prévia parecem estranhos</td><td>Confira padrão marcado e leituras digitadas</td></tr>\n    <tr><td>Um padrão não aparece na lista de seleção</td><td>Ele está Inativo — vá em Padrões e clique em \"Reativar\"</td></tr>\n    <tr><td>Balão vermelho do menu não some</td><td>Saia e entre de novo no SGO+, ou aguarde a próxima atualização</td></tr>\n  </table>\n\n  <h2 id=\"tplCertCal_ms15\">15. Glossário</h2>\n  <table>\n    <tr><th>Termo</th><th>Explicação simples</th></tr>\n    <tr><td>Padrão de referência</td><td>Instrumento mais preciso usado pra comparar e calibrar o equipamento do cliente</td></tr>\n    <tr><td>Bloco de ensaio</td><td>Grupo de resultados de uma mesma grandeza física</td></tr>\n    <tr><td>Ponto de calibração</td><td>Valor de referência testado, com 3 leituras</td></tr>\n    <tr><td>Tendência</td><td>Diferença entre a média medida e o valor de referência</td></tr>\n    <tr><td>Incerteza (U95)</td><td>Margem de confiança do resultado</td></tr>\n    <tr><td>Veff</td><td>Número técnico do cálculo de incerteza (graus de liberdade efetivos)</td></tr>\n    <tr><td>Fator K</td><td>Número usado pra chegar na incerteza final do certificado</td></tr>\n    <tr><td>|Tendência| + U95</td><td>Soma do módulo da tendência com U95; não constitui decisão de aceitação</td></tr>\n    <tr><td>Avaliação pelo cliente</td><td>Decisão final: Responsabilidade do setor de qualidade do cliente</td></tr>\n    <tr><td>Relatório Interpretativo</td><td>Documento separado que explica o certificado em linguagem simples, com IA</td></tr>\n  </table>\n\n  <a class=\"topo-link\" onclick=\"tplCertCal_irParaSecao_('tplCertCal_topoManual')\">↑ Topo</a>\n</div>`;\n}\n\nfunction certcalNumLeiturasTexto_() { return '3 leituras'; }\n\n// ---------------- Cliente ----------------\nfunction tplCertCal_buscarCliente() {\n  var cnpjInput = document.getElementById('certcal-cnpj').value;\n  var cnpjDigitos = String(cnpjInput || '').replace(/\\D/g, '');\n  if (cnpjDigitos.length !== 14) { tplCertCal_msg('certcal-cliente-status', 'error', 'Informe um CNPJ válido (14 dígitos).'); return; }\n\n  tplCertCal_msg('certcal-cliente-status', 'info', 'Buscando...');\n  tplCertCal_chamarApi('apiPesquisarClientes', { termo: cnpjDigitos }).then(function(res) {\n    var achado = (res.items || []).filter(function(c) { return String(c.CNPJ || '').replace(/\\D/g, '') === cnpjDigitos; })[0];\n    if (achado) {\n      tplCertCal_selecionarCliente({ ID: achado.ID, RAZAO_SOCIAL: achado.RAZAO_SOCIAL, CNPJ: achado.CNPJ, ENDERECO: achado.ENDERECO });\n      document.getElementById('certcal-cliente-status').innerHTML = '';\n      return;\n    }\n    document.getElementById('certcal-cliente-status').innerHTML = '';\n    document.getElementById('certcal-cliente-novo').classList.remove('hidden');\n    document.getElementById('certcal-novo-razaoSocial').value = '';\n    tplCertCal_chamarApi('apiConsultarCnpjPublico', { cnpj: cnpjDigitos }).then(function(dados) {\n      document.getElementById('certcal-novo-razaoSocial').value = dados.razaoSocial || '';\n      document.getElementById('certcal-novo-nomeFantasia').value = dados.nomeFantasia || '';\n      document.getElementById('certcal-novo-endereco').value = dados.endereco || '';\n      document.getElementById('certcal-novo-telefone').value = dados.telefone || '';\n      document.getElementById('certcal-novo-email').value = dados.email || '';\n    }).catch(function() { /* segue com formulário vazio se a consulta pública falhar */ });\n  }).catch(function(err) { tplCertCal_erro('certcal-cliente-status', err); });\n}\n\nfunction tplCertCal_criarCliente() {\n  var cnpjDigitos = String(document.getElementById('certcal-cnpj').value || '').replace(/\\D/g, '');\n  var payload = {\n    cnpj: cnpjDigitos,\n    razaoSocial: document.getElementById('certcal-novo-razaoSocial').value,\n    nomeFantasia: document.getElementById('certcal-novo-nomeFantasia').value,\n    endereco: document.getElementById('certcal-novo-endereco').value,\n    contato: document.getElementById('certcal-novo-contato').value,\n    email: document.getElementById('certcal-novo-email').value,\n    telefone: document.getElementById('certcal-novo-telefone').value\n  };\n  if (!payload.razaoSocial) { tplCertCal_msg('certcal-cliente-status', 'error', 'Informe a razão social.'); return; }\n\n  tplCertCal_chamarApi('apiCriarClienteComUnidade', payload).then(function(res) {\n    document.getElementById('certcal-cliente-novo').classList.add('hidden');\n    certcalState.unidadeSelecionadaId = res.unidade.ID;\n    tplCertCal_selecionarCliente(res.cliente);\n  }).catch(function(err) { tplCertCal_erro('certcal-cliente-status', err); });\n}\n\nfunction tplCertCal_selecionarCliente(cliente) {\n  certcalState.cliente = cliente;\n  var el = document.getElementById('certcal-cliente-selecionado');\n  el.classList.remove('hidden');\n  el.innerHTML = '<strong>' + (cliente.RAZAO_SOCIAL || '') + '</strong><br>CNPJ: ' + (cliente.CNPJ || '') + '<br>' + (cliente.ENDERECO || '');\n  document.getElementById('certcal-panel-equipamento').classList.remove('hidden');\n  tplCertCal_carregarUnidades();\n  tplCertCal_carregarEquipamentos();\n}\n\n// ---------------- Equipamento ----------------\nfunction tplCertCal_carregarUnidades() {\n  tplCertCal_chamarApi('apiListarUnidadesCliente', { clienteId: certcalState.cliente.ID }).then(function(res) {\n    var sel = document.getElementById('certcal-unidade');\n    sel.innerHTML = (res.items || []).map(function(u) { return '<option value=\"' + u.ID + '\">' + u.NOME_UNIDADE + '</option>'; }).join('');\n    if (certcalState.unidadeSelecionadaId) sel.value = certcalState.unidadeSelecionadaId;\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplCertCal_carregarEquipamentos() {\n  tplCertCal_chamarApi('apiListarEquipamentosCliente', { clienteId: certcalState.cliente.ID }).then(function(res) {\n    certcalState.equipamentos = res.items || [];\n    var sel = document.getElementById('certcal-equipamento-existente');\n    sel.innerHTML = '<option value=\"\">— selecione —</option>' + certcalState.equipamentos.map(function(e) {\n      return '<option value=\"' + e.ID + '\">' + (e.TIPO || '') + ' — TAG ' + (e.TAG || '') + '</option>';\n    }).join('');\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplCertCal_selecionarEquipamentoExistente() {\n  var id = document.getElementById('certcal-equipamento-existente').value;\n  var eq = certcalState.equipamentos.filter(function(e) { return e.ID === id; })[0];\n  if (!eq) { tplCertCal_msg('certcal-equipamento-status', 'error', 'Selecione um equipamento da lista.'); return; }\n  tplCertCal_confirmarEquipamento_(eq);\n}\n\nfunction tplCertCal_criarEquipamento() {\n  var payload = {\n    clienteId: certcalState.cliente.ID,\n    unidadeId: document.getElementById('certcal-unidade').value,\n    tipo: document.getElementById('certcal-eq-tipo').value,\n    fabricante: document.getElementById('certcal-eq-fabricante').value,\n    modelo: document.getElementById('certcal-eq-modelo').value,\n    serie: document.getElementById('certcal-eq-serie').value,\n    tag: document.getElementById('certcal-eq-tag').value,\n    setor: document.getElementById('certcal-eq-setor').value\n  };\n  if (!payload.tipo || !payload.tag) { tplCertCal_msg('certcal-equipamento-status', 'error', 'Informe ao menos a Descrição/Tipo e a TAG.'); return; }\n\n  tplCertCal_chamarApi('apiCriarEquipamento', payload).then(function(res) {\n    document.getElementById('certcal-equipamento-status').innerHTML = '';\n    tplCertCal_confirmarEquipamento_(res.equipamento);\n    tplCertCal_carregarEquipamentos();\n  }).catch(function(err) { tplCertCal_erro('certcal-equipamento-status', err); });\n}\n\nfunction tplCertCal_confirmarEquipamento_(eq) {\n  certcalState.equipamentoSelecionado = eq;\n  var el = document.getElementById('certcal-equipamento-selecionado');\n  el.classList.remove('hidden');\n  el.innerHTML = '<strong>' + (eq.TIPO || '') + '</strong> — TAG ' + (eq.TAG || '') + '<br>' + (eq.FABRICANTE || '') + ' / ' + (eq.MODELO || '');\n  ['certcal-panel-calibracao', 'certcal-panel-blocos', 'certcal-panel-responsabilidade', 'certcal-panel-fotos', 'certcal-panel-gerar'].forEach(function(id) {\n    document.getElementById(id).classList.remove('hidden');\n  });\n}\n\n// ---------------- Técnicos ----------------\nfunction tplCertCal_carregarTecnicos() {\n  return tplCertCal_chamarApi('apiListarTecnicos').then(function(res) {\n    certcalState.tecnicos = res.items || [];\n    var sel = document.getElementById('certcal-tecnico');\n    if (!sel) return;\n    var selecionadoAntes = sel.value;\n    sel.innerHTML = '<option value=\"\">— nenhum —</option>' + certcalState.tecnicos.map(function(t) {\n      return '<option value=\"' + t.ID + '\">' + t.NOME + '</option>';\n    }).join('');\n    if (selecionadoAntes) sel.value = selecionadoAntes;\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplCertCal_abrirNovoTecnico() { document.getElementById('certcal-tecnico-novo').classList.remove('hidden'); }\n\nfunction tplCertCal_criarTecnico() {\n  var nome = document.getElementById('certcal-tecnico-novo-nome').value;\n  if (!nome) { tplCertCal_msg('certcal-tecnico-status', 'error', 'Informe o nome do técnico.'); return; }\n\n  tplCertCal_chamarApi('apiCriarTecnicoSimples', { nome: nome }).then(function(res) {\n    document.getElementById('certcal-tecnico-novo').classList.add('hidden');\n    document.getElementById('certcal-tecnico-novo-nome').value = '';\n    document.getElementById('certcal-tecnico-status').innerHTML = '';\n    tplCertCal_carregarTecnicos().then(function() {\n      var sel = document.getElementById('certcal-tecnico');\n      if (sel && res.item) sel.value = res.item.ID;\n    });\n  }).catch(function(err) { tplCertCal_erro('certcal-tecnico-status', err); });\n}\n\n// ---------------- Padrões ----------------\nvar CERTCAL_STATUS_VALIDADE_LABELS_ = {\n  OK: { texto: 'Vigente', cor: '#1F6B2A' },\n  VENCENDO: { texto: 'Vence em até 30 dias', cor: '#7A5200' },\n  VENCIDO: { texto: 'Vencido', cor: '#A3261B' },\n  SEM_VALIDADE: { texto: 'Sem validade informada', cor: '#5F645F' },\n  VALIDADE_INVALIDA: { texto: 'Data inválida', cor: '#A3261B' }\n};\n\nfunction tplCertCal_numeroExibicao_(v) {\n  if (v === null || v === undefined || String(v).trim() === '') return '—';\n  var n = Number(v);\n  if (!isFinite(n)) return '—';\n  var s = n.toFixed(2);\n  if (s === '-0.00') s = '0.00';\n  return s.replace('.', ',');\n}\n\nfunction tplCertCal_pillStatusValidade_(p) {\n  var info = CERTCAL_STATUS_VALIDADE_LABELS_[p.statusValidade] || CERTCAL_STATUS_VALIDADE_LABELS_.SEM_VALIDADE;\n  return '<span style=\"display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;font-weight:700;background:' + info.cor + '22;color:' + info.cor + ';border:1px solid ' + info.cor + '55;\">' + info.texto + '</span>';\n}\n\nfunction tplCertCal_carregarPadroes() {\n  return Promise.all([\n    tplCertCal_chamarApi('apiListarPadroesAtivos'),\n    tplCertCal_chamarApi('apiListarPadroesTodos')\n  ]).then(function(res) {\n    certcalState.padroes = res[0].items || [];\n    certcalState.padroesTodos = res[1].items || [];\n    tplCertCal_renderPadroesTabela_();\n    tplCertCal_renderBlocos();\n    if (typeof carregarBadgesMenu_ === 'function') carregarBadgesMenu_();\n  }).catch(function(err) { console.error(err); });\n}\n\nfunction tplCertCal_renderPadroesTabela_() {\n  var alertaEl = document.getElementById('certcal-padroes-alerta');\n  var tabelaEl = document.getElementById('certcal-padroes-tabela');\n  if (!tabelaEl) return;\n\n  var lista = certcalState.padroesTodos || [];\n  if (!lista.length) {\n    tabelaEl.innerHTML = '<span class=\"muted\">Nenhum padrão cadastrado ainda. Use \"Cadastrar novo padrão\" logo abaixo.</span>';\n    if (alertaEl) alertaEl.innerHTML = '';\n    return;\n  }\n\n  var ativos = lista.filter(function(p) { return p.STATUS === 'ATIVO'; });\n  var graves = ativos.filter(function(p) { return p.statusValidade === 'VENCIDO' || p.statusValidade === 'VALIDADE_INVALIDA'; });\n  var vencendo = ativos.filter(function(p) { return p.statusValidade === 'VENCENDO'; });\n  var semData = ativos.filter(function(p) { return p.statusValidade === 'SEM_VALIDADE'; });\n  var tags = function(arr) { return arr.map(function(p) { return p.TAG; }).join(', '); };\n  if (alertaEl) {\n    alertaEl.innerHTML =\n      (graves.length ? '<div class=\"alert-box error\">' + (graves.length === 1 ? '1 padrão vencido ou com data inválida' : graves.length + ' padrões vencidos ou com data inválida') + ' (' + tags(graves) + '): não use em certificado até atualizar a validade em Editar.</div>' : '') +\n      (vencendo.length ? '<div class=\"alert-box info\">' + (vencendo.length === 1 ? '1 padrão vence' : vencendo.length + ' padrões vencem') + ' nos próximos 30 dias (' + tags(vencendo) + '). Programe a recalibração.</div>' : '') +\n      (semData.length ? '<div class=\"alert-box info\">' + (semData.length === 1 ? '1 padrão sem validade informada' : semData.length + ' padrões sem validade informada') + ' (' + tags(semData) + '). Informe a validade em Editar.</div>' : '');\n  }\n\n  var linhas = lista.map(function(p) {\n    var pdfCel = p.LINK_CERTIFICADO_PDF\n      ? '<a href=\"' + p.LINK_CERTIFICADO_PDF + '\" target=\"_blank\">Ver PDF</a>'\n      : '<span class=\"muted\">—</span>';\n    var acaoStatus = p.STATUS === 'ATIVO'\n      ? '<button class=\"btn btn-sm btn-danger\" onclick=\"tplCertCal_inativarPadrao(\\'' + p.ID + '\\')\">Inativar</button>'\n      : '<button class=\"btn btn-sm\" onclick=\"tplCertCal_reativarPadrao(\\'' + p.ID + '\\')\">Reativar</button>';\n    var acaoEditar = '<button class=\"btn btn-sm\" onclick=\"tplCertCal_abrirEditarPadrao(\\'' + p.ID + '\\')\">Editar</button>';\n    return '<tr>' +\n      '<td style=\"text-align:left;\">' + p.TAG + '<br><span class=\"muted\">' + p.DESCRICAO + '</span></td>' +\n      '<td>' + p.VALIDADE + '<br>' + tplCertCal_pillStatusValidade_(p) + '</td>' +\n      '<td>' + pdfCel + '<br><input type=\"file\" accept=\"application/pdf\" data-rotulo=\"' + (p.LINK_CERTIFICADO_PDF ? 'Substituir PDF' : 'Anexar PDF') + '\" style=\"margin-top:4px;\" onchange=\"tplCertCal_anexarCertificadoPadrao(\\'' + p.ID + '\\', this)\"></td>' +\n      '<td>' + acaoEditar + ' ' + acaoStatus + '</td>' +\n      '</tr>';\n  }).join('');\n\n  tabelaEl.innerHTML = '<div class=\"tabela-wrap\"><table class=\"resultado-table\"><thead><tr><th>Padrão</th><th>Validade</th><th>Certificado (PDF)</th><th>Ações</th></tr></thead><tbody>' + linhas + '</tbody></table></div>';\n}\n\nfunction tplCertCal_abrirNovoPadrao() { var edit = document.getElementById('certcal-padrao-editar'); if (edit) edit.classList.add('hidden'); document.getElementById('certcal-padrao-novo').classList.remove('hidden'); }\n\nfunction tplCertCal_criarPadrao() {\n  if (certcalState.salvandoPadrao) return;\n  certcalState.salvandoPadrao = true;\n  var payload = {\n    tag: document.getElementById('certcal-padrao-tag').value,\n    descricao: document.getElementById('certcal-padrao-descricao').value,\n    incertezaU95: document.getElementById('certcal-padrao-u95').value,\n    fatorK: document.getElementById('certcal-padrao-k').value,\n    veff: document.getElementById('certcal-padrao-veff').value,\n    certificadoNumero: document.getElementById('certcal-padrao-certificado').value,\n    validade: document.getElementById('certcal-padrao-validade').value\n  };\n\n  var arquivoInput = document.getElementById('certcal-padrao-certificado-arquivo');\n  var arquivo = arquivoInput && arquivoInput.files ? arquivoInput.files[0] : null;\n\n  (arquivo ? tplCertCal_lerArquivoComoBase64_(arquivo) : Promise.resolve(null)).then(function(lido) {\n    if (lido) {\n      payload.certificadoBase64 = lido.base64;\n      payload.certificadoMimeType = lido.mimeType;\n      payload.certificadoNomeArquivo = arquivo.name;\n    }\n    return tplCertCal_chamarApi('apiCriarPadrao', payload);\n  }).then(function() {\n    document.getElementById('certcal-padrao-novo').classList.add('hidden');\n    ['certcal-padrao-tag','certcal-padrao-descricao','certcal-padrao-certificado','certcal-padrao-validade'].forEach(function(id) { document.getElementById(id).value = ''; });\n    if (arquivoInput) arquivoInput.value = '';\n    tplCertCal_carregarPadroes();\n  }).catch(function(err) { tplCertCal_erro('certcal-padrao-status', err); }).finally(function() { certcalState.salvandoPadrao = false; });\n}\n\nfunction tplCertCal_inativarPadrao(padraoId) {\n  var pInat = (certcalState.padroesTodos || []).filter(function(x) { return x.ID === padraoId; })[0];\n  if (!confirm('Inativar o padrão ' + (pInat ? pInat.TAG : '') + '? Ele deixa de aparecer na escolha de padrões dos ensaios; o histórico é mantido e você pode reativá-lo depois.')) return;\n  tplCertCal_chamarApi('apiInativarPadrao', { padraoId: padraoId }).then(function() { tplCertCal_carregarPadroes(); }).catch(function(err) { tplCertCal_erro('certcal-padroes-alerta', err); });\n}\n\nfunction tplCertCal_reativarPadrao(padraoId) {\n  tplCertCal_chamarApi('apiReativarPadrao', { padraoId: padraoId }).then(function() { tplCertCal_carregarPadroes(); }).catch(function(err) { tplCertCal_erro('certcal-padroes-alerta', err); });\n}\n\nfunction tplCertCal_abrirEditarPadrao(padraoId) {\n  var p = (certcalState.padroesTodos || []).filter(function(x) { return x.ID === padraoId; })[0];\n  if (!p) return;\n  var novo = document.getElementById('certcal-padrao-novo');\n  if (novo) novo.classList.add('hidden');\n  document.getElementById('certcal-padrao-edit-id').value = p.ID;\n  document.getElementById('certcal-padrao-edit-tag').value = p.TAG || '';\n  document.getElementById('certcal-padrao-edit-descricao').value = p.DESCRICAO || '';\n  document.getElementById('certcal-padrao-edit-certificado').value = p.CERTIFICADO_NUMERO || '';\n  document.getElementById('certcal-padrao-edit-u95').value = String(p.INCERTEZA_U95 == null ? '' : p.INCERTEZA_U95).replace('.', ',');\n  document.getElementById('certcal-padrao-edit-k').value = String(p.FATOR_K == null ? 2 : p.FATOR_K).replace('.', ',');\n  document.getElementById('certcal-padrao-edit-veff').value = String(p.VEFF == null ? 0 : p.VEFF).replace('.', ',');\n  document.getElementById('certcal-padrao-edit-validade').value = p.VALIDADE || '';\n  document.getElementById('certcal-padrao-edit-status').innerHTML = '';\n  var editEl = document.getElementById('certcal-padrao-editar');\n  editEl.classList.remove('hidden');\n  if (editEl.scrollIntoView) editEl.scrollIntoView({ behavior: 'smooth', block: 'center' });\n}\n\nfunction tplCertCal_cancelarEdicaoPadrao() {\n  document.getElementById('certcal-padrao-editar').classList.add('hidden');\n}\n\nfunction tplCertCal_salvarEdicaoPadrao() {\n  if (certcalState.salvandoPadrao) return;\n  certcalState.salvandoPadrao = true;\n  var payload = {\n    padraoId: document.getElementById('certcal-padrao-edit-id').value,\n    tag: document.getElementById('certcal-padrao-edit-tag').value,\n    descricao: document.getElementById('certcal-padrao-edit-descricao').value,\n    incertezaU95: document.getElementById('certcal-padrao-edit-u95').value,\n    fatorK: document.getElementById('certcal-padrao-edit-k').value,\n    veff: document.getElementById('certcal-padrao-edit-veff').value,\n    certificadoNumero: document.getElementById('certcal-padrao-edit-certificado').value,\n    validade: document.getElementById('certcal-padrao-edit-validade').value\n  };\n\n  var arquivoInput = document.getElementById('certcal-padrao-edit-certificado-arquivo');\n  var arquivo = arquivoInput && arquivoInput.files ? arquivoInput.files[0] : null;\n\n  tplCertCal_msg('certcal-padrao-edit-status', 'info', 'Salvando...');\n  (arquivo ? tplCertCal_lerArquivoComoBase64_(arquivo) : Promise.resolve(null)).then(function(lido) {\n    if (lido) {\n      payload.certificadoBase64 = lido.base64;\n      payload.certificadoMimeType = lido.mimeType;\n      payload.certificadoNomeArquivo = arquivo.name;\n    }\n    return tplCertCal_chamarApi('apiAtualizarPadrao', payload);\n  }).then(function() {\n    document.getElementById('certcal-padrao-editar').classList.add('hidden');\n    if (arquivoInput) arquivoInput.value = '';\n    tplCertCal_carregarPadroes();\n  }).catch(function(err) { tplCertCal_erro('certcal-padrao-edit-status', err); }).finally(function() { certcalState.salvandoPadrao = false; });\n}\n\nfunction tplCertCal_anexarCertificadoPadrao(padraoId, inputEl) {\n  var arquivo = inputEl && inputEl.files ? inputEl.files[0] : null;\n  if (!arquivo) return;\n  tplCertCal_lerArquivoComoBase64_(arquivo).then(function(lido) {\n    return tplCertCal_chamarApi('apiAnexarCertificadoPadrao', {\n      padraoId: padraoId, certificadoBase64: lido.base64, certificadoMimeType: lido.mimeType, certificadoNomeArquivo: arquivo.name\n    });\n  }).then(function() { tplCertCal_carregarPadroes(); }).catch(function(err) { tplCertCal_erro('certcal-padroes-alerta', err); });\n}\n\n// ---------------- Blocos de ensaio ----------------\nfunction tplCertCal_adicionarBloco() {\n  certcalState.blocos.push({ titulo: '', unidade: '', padroesIds: [], pontos: [{ nominal: '', leituras: ['', '', ''] }] });\n  tplCertCal_renderBlocos();\n}\n\nfunction tplCertCal_removerBloco(idx) {\n  var bRem = certcalState.blocos[idx] || { pontos: [] };\n  var nDig = (bRem.pontos || []).filter(function(pt) { return String(pt.nominal || '').trim() || (pt.leituras || []).some(function(l) { return String(l || '').trim(); }); }).length;\n  if (nDig && !confirm('Remover o bloco ' + (idx + 1) + (bRem.titulo ? ' (' + bRem.titulo + ')' : '') + ' e os ' + nDig + ' ponto(s) digitados? Esta ação não pode ser desfeita.')) return;\n  certcalState.blocos.splice(idx, 1);\n  tplCertCal_renderBlocos();\n}\n\nfunction tplCertCal_adicionarPonto(blocoIdx) {\n  certcalState.blocos[blocoIdx].pontos.push({ nominal: '', leituras: ['', '', ''] });\n  tplCertCal_renderBlocos();\n}\n\nfunction tplCertCal_removerPonto(blocoIdx, pontoIdx) {\n  var ptRem = certcalState.blocos[blocoIdx].pontos[pontoIdx] || {};\n  var temDado = String(ptRem.nominal || '').trim() || (ptRem.leituras || []).some(function(l) { return String(l || '').trim(); });\n  if (temDado && !confirm('Remover o ponto ' + (pontoIdx + 1) + ' do bloco ' + (blocoIdx + 1) + ' com os valores digitados?')) return;\n  certcalState.blocos[blocoIdx].pontos.splice(pontoIdx, 1);\n  tplCertCal_renderBlocos();\n}\n\nfunction tplCertCal_atualizarBlocoCampo(blocoIdx, campo, valor) { certcalState.blocos[blocoIdx][campo] = valor; tplCertCal_atualizarAvisoPadrao_(blocoIdx); }\n\nfunction tplCertCal_atualizarPontoNominal(blocoIdx, pontoIdx, valor) { certcalState.blocos[blocoIdx].pontos[pontoIdx].nominal = valor; }\n\nfunction tplCertCal_atualizarLeitura(blocoIdx, pontoIdx, leituraIdx, valor) {\n  certcalState.blocos[blocoIdx].pontos[pontoIdx].leituras[leituraIdx] = valor;\n}\n\nfunction tplCertCal_alternarPadraoBloco(blocoIdx, padraoId, checked) {\n  var bloco = certcalState.blocos[blocoIdx];\n  var idx = bloco.padroesIds.indexOf(padraoId);\n  if (checked && idx === -1) bloco.padroesIds.push(padraoId);\n  if (!checked && idx !== -1) bloco.padroesIds.splice(idx, 1);\n  tplCertCal_atualizarAvisoPadrao_(blocoIdx);\n}\n\nfunction tplCertCal_renderBlocos() {\n  var el = document.getElementById('certcal-blocos-lista');\n  if (!el) return;\n\n  el.innerHTML = certcalState.blocos.map(function(bloco, bi) {\n    var padroesHtml = certcalState.padroes.map(function(p) {\n      var marcado = bloco.padroesIds.indexOf(p.ID) !== -1 ? 'checked' : '';\n      return '<div class=\"checkbox-row\"><input type=\"checkbox\" id=\"certcal-padrao-' + bi + '-' + p.ID + '\" ' + marcado +\n        ' onchange=\"tplCertCal_alternarPadraoBloco(' + bi + ',\\'' + p.ID + '\\',this.checked)\">' +\n        '<label for=\"certcal-padrao-' + bi + '-' + p.ID + '\">' + p.TAG + ' — ' + p.DESCRICAO + '</label> ' + tplCertCal_pillStatusValidade_(p) + '</div>';\n    }).join('') || '<span class=\"muted\">Cadastre um padrão acima antes de calcular.</span>';\n\n    var pontosHtml = bloco.pontos.map(function(ponto, pi) {\n      var leiturasHtml = ponto.leituras.map(function(l, li) {\n        return '<td><input value=\"' + l + '\" oninput=\"tplCertCal_atualizarLeitura(' + bi + ',' + pi + ',' + li + ',this.value)\"></td>';\n      }).join('');\n      return '<tr><td><input value=\"' + ponto.nominal + '\" oninput=\"tplCertCal_atualizarPontoNominal(' + bi + ',' + pi + ',this.value)\"></td>' +\n        leiturasHtml + '<td><button class=\"btn btn-sm btn-danger\" onclick=\"tplCertCal_removerPonto(' + bi + ',' + pi + ')\">Remover</button></td></tr>';\n    }).join('');\n\n    var avisoPadrao = tplCertCal_avisoPadraoDivergente_(bloco);\n    return '<div class=\"bloco-card\">' +\n      '<div class=\"bloco-card-head\"><strong>Bloco ' + (bi + 1) + '</strong><button class=\"btn btn-sm btn-danger\" onclick=\"tplCertCal_removerBloco(' + bi + ')\">Remover bloco</button></div>' +\n      '<div class=\"grid-2\">' +\n      '<div><label>Título (grandeza/canal)</label><input value=\"' + bloco.titulo + '\" placeholder=\"Ex.: Sensor Interno — Temperatura\" oninput=\"tplCertCal_atualizarBlocoCampo(' + bi + ',\\'titulo\\',this.value)\"></div>' +\n      '<div><label>Unidade</label><input value=\"' + bloco.unidade + '\" placeholder=\"Ex.: °C\" oninput=\"tplCertCal_atualizarBlocoCampo(' + bi + ',\\'unidade\\',this.value)\"></div>' +\n      '</div>' +\n      '<label>Padrões de referência usados neste bloco</label>' + padroesHtml + '<div id=\"certcal-aviso-' + bi + '\">' + avisoPadrao + '</div>' +\n      '<table class=\"pontos-table\"><thead><tr><th>Referência (Nominal)</th><th>Ensaio 1</th><th>Ensaio 2</th><th>Ensaio 3</th><th></th></tr></thead><tbody>' + pontosHtml + '</tbody></table>' +\n      '<button class=\"btn btn-sm\" onclick=\"tplCertCal_adicionarPonto(' + bi + ')\">+ Adicionar ponto</button>' +\n      '</div>';\n  }).join('');\n}\n\nfunction tplCertCal_montarBlocosPayload_() {\n  return certcalState.blocos.map(function(b) {\n    return {\n      titulo: b.titulo,\n      unidade: b.unidade,\n      padroesIds: b.padroesIds,\n      pontos: b.pontos.map(function(p) {\n        return { nominal: p.nominal, leituras: p.leituras.slice() };\n      })\n    };\n  });\n}\n\nfunction tplCertCal_calcularPreview() {\n  var payload = { blocos: tplCertCal_montarBlocosPayload_() };\n  tplCertCal_msg('certcal-preview-resultado', 'info', 'Calculando...');\n  tplCertCal_chamarApi('apiCalcularPreview', payload).then(function(res) {\n    var html = res.blocos.map(function(b) {\n      var cab = '<th>Nominal</th><th>Ensaio 1</th><th>Ensaio 2</th><th>Ensaio 3</th><th>Média</th><th>Tendência</th><th>U95</th><th>Veff</th><th>|Tendência| + U95</th>';\n      var linhas = b.resultados.map(function(r) {\n        return '<tr><td>' + tplCertCal_numeroExibicao_(r.nominal) + '</td><td>' + tplCertCal_numeroExibicao_(r.leituras[0]) + '</td><td>' + tplCertCal_numeroExibicao_(r.leituras[1]) + '</td><td>' + tplCertCal_numeroExibicao_(r.leituras[2]) + '</td>' +\n          '<td>' + tplCertCal_numeroExibicao_(r.media) + '</td><td>' + tplCertCal_numeroExibicao_(r.tendencia) + '</td><td>' + tplCertCal_numeroExibicao_(r.incertezaU95) + '</td>' +\n          '<td>' + tplCertCal_fmtVeff_(r.veff) + '</td><td>' + tplCertCal_numeroExibicao_(r.erroMaximo) + '</td></tr>';\n      }).join('');\n      return '<h3 style=\"font-size:13px;margin:14px 0 4px;color:var(--text-strong);\">' + b.titulo + ' (' + b.unidade + ')</h3>' +\n        '<table class=\"resultado-table\"><thead><tr>' + cab + '</tr></thead><tbody>' + linhas + '</tbody></table>' +\n        '<p class=\"muted\">Maior tendência em módulo: ' + tplCertCal_numeroExibicao_(b.piorTendencia) + ' | Pior U95: ' + tplCertCal_numeroExibicao_(b.piorIncertezaU95) +\n        ' (Veff ' + tplCertCal_fmtVeff_(b.piorIncertezaVeff) + ', K ' + tplCertCal_numeroExibicao_(b.piorIncertezaK) + ') | Maior |Tendência| + U95: ' + tplCertCal_numeroExibicao_(b.piorErroMaximo) + '</p>';\n    }).join('');\n    document.getElementById('certcal-preview-resultado').innerHTML = html;\n  }).catch(function(err) { tplCertCal_erro('certcal-preview-resultado', err); });\n}\n\n// ---------------- Fotos ----------------\nfunction tplCertCal_lerArquivoComoBase64_(file) {\n  return new Promise(function(resolve) {\n    var reader = new FileReader();\n    reader.onload = function(e) {\n      var resultado = e.target.result || '';\n      var base64 = resultado.indexOf(',') !== -1 ? resultado.split(',')[1] : resultado;\n      resolve({ base64: base64, mimeType: file.type || 'image/jpeg' });\n    };\n    reader.onerror = function() { resolve(null); };\n    reader.readAsDataURL(file);\n  });\n}\n\nfunction tplCertCal_onFotosSelecionadas() {\n  var input = document.getElementById('certcal-fotos-input');\n  var arquivos = Array.prototype.slice.call(input.files || []).slice(0, 8);\n  Promise.all(arquivos.map(tplCertCal_lerArquivoComoBase64_)).then(function(lidos) {\n    lidos.filter(Boolean).forEach(function(f) { certcalState.fotos.push({ base64: f.base64, mimeType: f.mimeType, legenda: '' }); });\n    tplCertCal_renderFotos_();\n  });\n}\n\nfunction tplCertCal_atualizarLegendaFoto(idx, valor) { certcalState.fotos[idx].legenda = valor; }\n\nfunction tplCertCal_removerFoto(idx) { certcalState.fotos.splice(idx, 1); tplCertCal_renderFotos_(); }\n\nfunction tplCertCal_renderFotos_() {\n  var el = document.getElementById('certcal-fotos-lista');\n  if (!el) return;\n  el.innerHTML = certcalState.fotos.map(function(f, i) {\n    return '<div class=\"foto-thumb\"><img src=\"data:' + f.mimeType + ';base64,' + f.base64 + '\">' +\n      '<input placeholder=\"Legenda (opcional)\" value=\"' + f.legenda + '\" oninput=\"tplCertCal_atualizarLegendaFoto(' + i + ',this.value)\">' +\n      '<button class=\"btn btn-sm btn-danger\" onclick=\"tplCertCal_removerFoto(' + i + ')\">Remover</button></div>';\n  }).join('');\n}\n\n// ---------------- Geração ----------------\nfunction tplCertCal_abrirHtmlEmNovaAba_(novaJanela, html) {\n  if (!novaJanela) return;\n  novaJanela.document.open();\n  novaJanela.document.write(html);\n  novaJanela.document.close();\n}\n\n\nfunction tplCertCal_alternarProximaCalibracao_() {\n  var solicitada = document.getElementById('certcal-proxima-sim').checked;\n  document.getElementById('certcal-proxima-campos').classList.toggle('hidden', !solicitada);\n  ['data', 'solicitante', 'cargo-setor', 'referencia', 'observacao'].forEach(function(campo) {\n    var el = document.getElementById('certcal-proxima-' + campo);\n    el.disabled = !solicitada;\n    el.required = solicitada && campo !== 'observacao';\n    if (!solicitada) el.value = '';\n  });\n}\n\nfunction tplCertCal_montarProximaCalibracaoPayload_() {\n  var sim = document.getElementById('certcal-proxima-sim');\n  var solicitada = !!(sim && sim.checked);\n  var p = { solicitada: solicitada, data: '', solicitante: '', cargoSetor: '', referencia: '', observacao: '' };\n  if (!solicitada) return p;\n  ['data', 'solicitante', 'cargoSetor', 'referencia', 'observacao'].forEach(function(campo) {\n    var id = campo === 'cargoSetor' ? 'cargo-setor' : campo;\n    p[campo] = document.getElementById('certcal-proxima-' + id).value.trim();\n  });\n  if (!p.data || !p.solicitante || !p.cargoSetor || !p.referencia) throw new Error('Informe data, nome do solicitante, cargo/setor e referência da solicitação de próxima calibração.');\n  var m = /^(\\d{2})\\/(\\d{2})\\/(\\d{4})$/.exec(p.data);\n  if (!m) throw new Error('Informe a data solicitada no formato dd/mm/aaaa.');\n  var d = new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));\n  if (d.getFullYear() !== Number(m[3]) || d.getMonth() !== Number(m[2]) - 1 || d.getDate() !== Number(m[1])) throw new Error('Data solicitada de próxima calibração inválida.');\n  return p;\n}\n\nfunction tplCertCal_avisosHtml_(res) {\n  return (Array.isArray(res.avisos) ? res.avisos : []).map(function(aviso) {\n    var seguro = String(aviso).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');\n    return '<p role=\"status\"><strong>Pendência:</strong> ' + seguro + '</p>';\n  }).join('');\n}\n\nfunction tplCertCal_gerarCertificado() {\n  if (!certcalState.cliente || !certcalState.equipamentoSelecionado) {\n    tplCertCal_msg('certcal-resultado-certificado', 'error', 'Selecione o cliente e o equipamento antes de gerar.');\n    return;\n  }\n  if (!certcalState.blocos.length) {\n    tplCertCal_msg('certcal-resultado-certificado', 'error', 'Adicione ao menos 1 bloco de ensaio.');\n    return;\n  }\n\n  var proximaCalibracao;\n  try { proximaCalibracao = tplCertCal_montarProximaCalibracaoPayload_(); } catch (err) { tplCertCal_erro('certcal-resultado-certificado', err); return; }\n  var payload = {\n    clienteId: certcalState.cliente.ID,\n    equipamentoId: certcalState.equipamentoSelecionado.ID,\n    tecnicoId: document.getElementById('certcal-tecnico').value,\n    tecnicoExecutorLivre: document.getElementById('certcal-tecnico-livre').value,\n    dataCalibracao: document.getElementById('certcal-data-calibracao').value,\n    proximaCalibracao: proximaCalibracao,\n    localCalibracao: document.getElementById('certcal-local-lab').checked ? 'LABORATORIO' : 'CLIENTE',\n    temperaturaAmbiente: document.getElementById('certcal-temp-ambiente').value,\n    umidadeRelativa: document.getElementById('certcal-umidade-ambiente').value,\n    blocos: tplCertCal_montarBlocosPayload_(),\n    fotos: certcalState.fotos\n  };\n\n  var btn = document.getElementById('certcal-btn-gerar');\n  btn.disabled = true;\n  tplCertCal_msg('certcal-resultado-certificado', 'info', 'Calculando e montando o certificado...');\n  var novaJanela = window.open('', '_blank');\n  if (novaJanela) novaJanela.document.write('<p style=\"font-family:Arial,sans-serif;padding:40px;color:#374151;\">Gerando certificado, aguarde...</p>');\n\n  tplCertCal_chamarApi('apiGerarCertificado', payload).then(function(res) {\n    btn.disabled = false;\n    certcalState.ultimoCertificadoId = res.certificadoId;\n    tplCertCal_abrirHtmlEmNovaAba_(novaJanela, res.html);\n    tplCertCal_msg('certcal-resultado-certificado', res.avisos && res.avisos.length ? 'info' : 'success', 'Certificado nº ' + res.numeroCertificado + ' emitido e salvo no SGO+ (pasta do cliente) — aberto em nova aba. <a href=\"' + res.linkPdf + '\" target=\"_blank\" style=\"color:var(--bc-action);\">Abrir PDF salvo</a>' + tplCertCal_avisosHtml_(res));\n    document.getElementById('certcal-btn-interpretativo').classList.remove('hidden');\n  }).catch(function(err) {\n    btn.disabled = false;\n    if (novaJanela) novaJanela.close();\n    tplCertCal_erro('certcal-resultado-certificado', err);\n  });\n}\n\nfunction tplCertCal_gerarRelatorioInterpretativo() {\n  if (!certcalState.ultimoCertificadoId) return;\n  var btn = document.getElementById('certcal-btn-interpretativo');\n  btn.disabled = true;\n  tplCertCal_msg('certcal-resultado-interpretativo', 'info', 'Preparando relatório interpretativo a partir dos resultados salvos...');\n  var novaJanela = window.open('', '_blank');\n  if (novaJanela) novaJanela.document.write('<p style=\"font-family:Arial,sans-serif;padding:40px;color:#374151;\">Gerando relatório interpretativo, aguarde...</p>');\n\n  tplCertCal_chamarApi('apiGerarRelatorioInterpretativo', { certificadoId: certcalState.ultimoCertificadoId }).then(function(res) {\n    btn.disabled = false;\n    tplCertCal_abrirHtmlEmNovaAba_(novaJanela, res.html);\n    tplCertCal_msg('certcal-resultado-interpretativo', res.avisos && res.avisos.length ? 'info' : 'success', 'Relatório interpretativo gerado e salvo no SGO+ (pasta do cliente) — aberto em nova aba. <a href=\"' + res.linkPdf + '\" target=\"_blank\" style=\"color:var(--bc-action);\">Abrir PDF salvo</a>' + tplCertCal_avisosHtml_(res));\n  }).catch(function(err) {\n    btn.disabled = false;\n    if (novaJanela) novaJanela.close();\n    tplCertCal_erro('certcal-resultado-interpretativo', err);\n  });\n}\n\n// ---------------- Relatórios gerenciais ----------------\nfunction tplCertCal_gerarRelatorioGestao_(tipo) {\n  var renovacao = tipo === 'RENOVACAO';\n  var periodoEl = document.getElementById('certcal-gestao-periodo');\n  var payload = renovacao ? {} : { periodoDias: Number(periodoEl && periodoEl.value || 90) };\n  var api = renovacao ? 'apiGerarRelatorioRenovacao' : 'apiGerarRelatorioDesempenho';\n  var nome = renovacao ? 'plano de renovação e auditoria' : 'relatório de desempenho';\n  var novaJanela = window.open('', '_blank');\n  if (novaJanela) novaJanela.document.write('<p style=\"font-family:Arial;padding:20px\">Gerando ' + nome + ' com interpretação por IA...</p>');\n  tplCertCal_msg('certcal-gestao-relatorios-status', 'info', 'Analisando os dados e preparando o ' + nome + '...');\n  tplCertCal_chamarApi(api, payload).then(function(res) {\n    tplCertCal_abrirHtmlEmNovaAba_(novaJanela, res.html);\n    tplCertCal_msg('certcal-gestao-relatorios-status', 'success', 'Relatório gerado. Use “Imprimir / Salvar PDF” na nova aba.');\n  }).catch(function(err) {\n    if (novaJanela) novaJanela.close();\n    tplCertCal_erro('certcal-gestao-relatorios-status', err);\n  });\n}\n\n// ---------------- Busca por CNPJ ----------------\nfunction tplCertCal_buscarPorCnpj() {\n  var cnpjDigitos = String(document.getElementById('certcal-busca-cnpj').value || '').replace(/\\D/g, '');\n  if (cnpjDigitos.length !== 14) { tplCertCal_msg('certcal-busca-resultado', 'error', 'Informe um CNPJ válido (14 dígitos).'); return; }\n\n  tplCertCal_msg('certcal-busca-resultado', 'info', 'Buscando...');\n  tplCertCal_chamarApi('apiBuscarCertificadosPorCnpj', { cnpj: cnpjDigitos }).then(function(res) {\n    if (!res.cliente) { tplCertCal_msg('certcal-busca-resultado', 'error', 'Nenhum cliente encontrado com este CNPJ.'); return; }\n    if (!res.items.length) { tplCertCal_msg('certcal-busca-resultado', 'info', res.cliente.razaoSocial + ' — nenhum certificado emitido ainda.'); return; }\n\n    var linhas = res.items.map(function(it) {\n      return '<div class=\"cert-item-row\"><span><strong>Nº ' + it.numeroCertificado + '</strong> — ' + it.equipamentoDescricao + ' (TAG ' + it.equipamentoTag + ') — ' + it.dataCalibracao + '</span>' +\n        '<span><button class=\"btn btn-sm\" onclick=\"tplCertCal_reabrirCertificado(\\'' + it.id + '\\')\">Reabrir certificado</button>' +\n        (it.linkPdfRelatorioInterpretativo ? ' <a href=\"' + it.linkPdfRelatorioInterpretativo + '\" target=\"_blank\" class=\"btn btn-sm\" style=\"text-decoration:none;display:inline-block;\">Relatório interpretativo</a>' : '') +\n        '</span></div>';\n    }).join('');\n    document.getElementById('certcal-busca-resultado').innerHTML = '<p class=\"muted\">' + res.cliente.razaoSocial + '</p>' + linhas;\n  }).catch(function(err) { tplCertCal_erro('certcal-busca-resultado', err); });\n}\n\nfunction tplCertCal_reabrirCertificado(certificadoId) {\n  var novaJanela = window.open('', '_blank');\n  if (novaJanela) novaJanela.document.write('<p style=\"font-family:Arial,sans-serif;padding:40px;color:#374151;\">Abrindo certificado, aguarde...</p>');\n  tplCertCal_chamarApi('apiReabrirCertificado', { certificadoId: certificadoId }).then(function(res) {\n    tplCertCal_abrirHtmlEmNovaAba_(novaJanela, res.html);\n  }).catch(function(err) {\n    if (novaJanela) novaJanela.close();\n    tplCertCal_erro('certcal-busca-resultado', err);\n  });\n}\n<\/script>\n";function CertCal_obterConteudoModulo(){var adicional=HtmlService.createHtmlOutputFromFile("JS_Padroes_Documentos").getContent().replace(/<\/?script>/g,"");return CERTCAL_CONTEUDO_MODULO.replace("<\/script>",function(){return adicional+"\n<\/script>"})}
